 "content": "def transform(grid):
    """Replace every isolated marker by a copy of the nearby 3x2 pattern."""
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    # Locate the 3x3 reference object, whose upper-left is the only position
    # with two background-colored missing cells in its top row.
    ref = None
    for r in range(h - 2):
        for c in range(w - 2):
            if grid[r][c] == bg and grid[r][c+1] == bg and grid[r+1][c] != bg:
                ref = (r, c)
                break
        if ref:
            break
    if ref is None:
        return out
    rr, cc = ref
    # The marker is replaced by the right-hand column of the reference object;
    # the two cells immediately above it are also painted from the reference.
    # In the demonstrated transformations each marker anchors the pattern at
    # its own coordinate (the reference marker coordinate corresponds to center).
    # Extract the 3x2 motif to the right/around its central cell.
    marker_color = grid[rr+1][cc+1]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker_color
              and (r, c) != (rr+1, cc+1)]
    # Pattern cells relative to the anchor marker at (rr+1,cc+1).
    motif = {}
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if grid[rr+1+dr][cc+1+dc] != bg:
                motif[(dr, dc)] = grid[rr+1+dr][cc+1+dc]
    for r, c in points:
        for (dr, dc), value in motif.items():
            if 0 <= r+dr < h and 0 <= c+dc < w:
                out[r+dr][c+dc] = value
    return out
